let particles = [];

function setup() {
  createCanvas(400, 300);
  for (let i = 0; i < 50; i++) {
    particles.push({
      x: random(width),
      y: random(height),
      vx: random(-2, 2),
      vy: random(-2, 2),
      size: random(3, 8)
    });
  }
}

function draw() {
  background(20, 20, 40);

  for (let p of particles) {
    // Draw particle
    fill(150, 200, 255);
    noStroke();
    ellipse(p.x, p.y, p.size);

    // Update position
    p.x += p.vx;
    p.y += p.vy;

    // Bounce off edges
    if (p.x < 0 || p.x > width) p.vx *= -1;
    if (p.y < 0 || p.y > height) p.vy *= -1;
  }
}

